The CAS retry loop already prevents lost updates. I changed the joins so the supervisor waits for both workers before propagating a worker panic.

```rust
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn increment(c: &AtomicUsize) {
    let mut observed = c.load(Ordering::SeqCst);

    loop {
        match c.compare_exchange(
            observed,
            observed + 1,
            Ordering::SeqCst,
            Ordering::SeqCst,
        ) {
            Ok(_) => return,
            Err(actual) => observed = actual,
        }
    }
}

fn w1(c: Arc<AtomicUsize>) {
    increment(&c);
}

fn w2(c: Arc<AtomicUsize>) {
    increment(&c);
}

fn main() {
    let c = Arc::new(AtomicUsize::new(0));

    let c1 = Arc::clone(&c);
    let t1 = thread::spawn(move || w1(c1));

    let c2 = Arc::clone(&c);
    let t2 = thread::spawn(move || w2(c2));

    let result1 = t1.join();
    let result2 = t2.join();
    result1.unwrap();
    result2.unwrap();

    assert_eq!(c.load(Ordering::SeqCst), 2);
    println!("DONE done=1");
}
